// The weekly digest. Titles and journals come from Crossref; only the summary and tag come from the AI reply,
// and only when the reply's DOI matches a paper that was actually sent.
const WINE = '#4a1424', RED = '#b3202a', INK = '#1d1416', MUTED = '#5f5456', LINE = '#d9d4d5';
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const SEARCH = 'islamic finance, sukuk, green sukuk';
const TO = 'team@example.org';
const today = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
const newItems = $('Find new items').all().map(i => i.json);
const noAbstract = newItems.filter(d => !d.has_abstract);
const meta = (d, extra) => '<div style="color:' + MUTED + ';font-size:12px;margin-top:2px">' + esc(d.journal) + ' &middot; <a href="https://doi.org/' + esc(d.doi_link) + '" style="color:' + RED + '">doi.org/' + esc(d.doi_link) + '</a>' + (extra || '') + '</div>';
const listed = noAbstract.map(d => '<li style="margin-bottom:8px">' + esc(d.title) + meta(d, ' &middot; <i>no abstract available, not summarised</i>') + '</li>').join('');
const shell = (inner, footer) =>
  '<div style="font-family:Helvetica,Arial,sans-serif;color:' + INK + ';max-width:640px;margin:0 auto;border:1px solid ' + LINE + ';line-height:1.5;font-size:14px">' +
  '<div style="background:' + WINE + ';color:#fff;padding:20px 26px"><div style="font-family:Georgia,serif;font-size:20px">Weekly research digest</div>' +
  '<div style="width:48px;height:2px;background:' + RED + ';margin:8px 0 6px"></div><div style="font-size:13px">' + today + ' &middot; Crossref records published in the last 7 days &middot; search: ' + esc(SEARCH) + '</div></div>' +
  '<div style="padding:20px 26px">' + inner + '</div>' +
  '<div style="border-top:1px solid ' + LINE + ';padding:12px 26px;font-size:12px;color:' + MUTED + '">This digest lists what Crossref returned for the search terms. It is not a quality filter. ' +
  'Check the journal and read the paper before relying on it. Summaries are written by AI from the abstract only. ' + footer + '</div></div>';
const h3 = t => '<h3 style="color:' + WINE + ';margin:18px 0 8px;font-size:15px">' + t + '</h3>';
const r = $input.first().json;
if (!r || r.failed) return [];
const sent = new Set($('Prepare AI request').first().json.sent_dois);
const byDoi = {};
const dropped = [];
for (const s of (r.items || [])) {
  const k = String(s.doi || '').trim().toLowerCase();
  if (!sent.has(k) || byDoi[k]) { dropped.push(String(s.doi)); continue; }
  byDoi[k] = s;
}
const summarised = newItems.filter(d => d.has_abstract && byDoi[d.doi]);
const missing = newItems.filter(d => d.has_abstract && !byDoi[d.doi]);
const card = d => {
  const s = byDoi[d.doi];
  const lang = s.abstract_language && !/^english$/i.test(s.abstract_language) ? ' &middot; abstract in ' + esc(s.abstract_language) : '';
  return '<div style="border:1px solid ' + LINE + ';padding:10px 14px;margin:0 0 10px"><div style="font-weight:bold">' + esc(d.title) + '</div>' +
    meta(d, ' &middot; <b style="color:' + RED + '">' + esc(s.relevance) + '</b>' + lang) + '<div style="margin-top:6px">' + esc(s.summary) + '</div></div>';
};
let inner = h3('Summarised from the abstract') + (summarised.map(card).join('') || '<p style="color:' + MUTED + '">No summaries came back.</p>');
if (missing.length) inner += h3('Sent for a summary, none came back') + '<ul style="padding-left:18px;margin:0">' + missing.map(d => '<li style="margin-bottom:8px">' + esc(d.title) + meta(d) + '</li>').join('') + '</ul>';
if (noAbstract.length) inner += h3('Listed without a summary') + '<ul style="padding-left:18px;margin:0">' + listed + '</ul>';
const footer = 'New items this week: ' + newItems.length + '. Sent for a summary: ' + sent.size + '. Summaries received: ' + summarised.length + '. Listed without an abstract: ' + noAbstract.length + '.';
return [{ json: { to: TO, subject: 'Weekly research digest: ' + today, html: shell(inner, footer),
  counts: { new_items: newItems.length, sent: sent.size, summaries: summarised.length, no_abstract: noAbstract.length, missing: missing.length, dropped_replies: dropped.length },
  summarised_dois: summarised.map(d => d.doi), dropped_dois: dropped } }];

// Runs only after the digest email has gone, so next week's run skips these DOIs. If the email fails, nothing is logged.
let summarised = [];
try { summarised = $('Build digest').first().json.summarised_dois || []; } catch (e) { summarised = []; }
const done = new Set(summarised);
const pad = n => String(n).padStart(2, '0');
const t = new Date();
const date = t.getFullYear() + '-' + pad(t.getMonth() + 1) + '-' + pad(t.getDate());
return $('Find new items').all().map(i => i.json).map(d => ({ json: {
  DOI: d.doi, Title: d.title, 'Date sent': date,
  Status: done.has(d.doi) ? 'summarised' : (d.has_abstract ? 'sent, no summary returned' : 'listed, no abstract') } }));

// Used only when there are new items and none of them has an abstract: a titles-only digest, nothing goes to the AI step.
const WINE = '#4a1424', RED = '#b3202a', INK = '#1d1416', MUTED = '#5f5456', LINE = '#d9d4d5';
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const SEARCH = 'islamic finance, sukuk, green sukuk';
const TO = 'team@example.org';
const today = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
const newItems = $('Find new items').all().map(i => i.json);
